-- The sign off: one line of ks5-20 moves from twenty eight to thirty two.
do $$
declare signoff jsonb;
begin
  select l.slides->29 into signoff from schools.school_lessons l where l.module_id = 'ks5-20-ai-mastery-data-rights';
  if signoff is null or signoff->>'heading' is distinct from 'DiGi signs off' then
    raise exception '358: ks5-20 slide 30 is not the DiGi sign off';
  end if;
