-- The table grew by four, and nothing else moved but the one sign off line.
do $$
declare before_n int; after_n int; moved int; line text;
begin
  select count(*) into before_n from schools.school_lessons_backup_358;
  select count(*) into after_n from schools.school_lessons;
  if after_n is distinct from before_n + 4 then
    raise exception '358: expected four new rows, the table went from % to %', before_n, after_n;
  end if;
  select count(*) into moved
  from schools.school_lessons l
  join schools.school_lessons_backup_358 b using (module_id)
  where l.module_id <> 'ks5-20-ai-mastery-data-rights'
    and row_to_json(l)::text is distinct from row_to_json(b)::text;
  if moved <> 0 then
    raise exception '358: % other lesson(s) moved', moved;
  end if;
  select l.slides->29->'lines'->>0 into line from schools.school_lessons l where l.module_id = 'ks5-20-ai-mastery-data-rights';
  if line is distinct from 'Thirty two modules, and here is where they were all heading. ⭐' then
    raise exception '358: the sign off reads %', line;
  end if;
  if (select count(*) from schools.school_lessons l join schools.school_lessons_backup_358 b using (module_id)
      where l.module_id = 'ks5-20-ai-mastery-data-rights'
        and (l.slides #- '{29,lines,0}')::text is distinct from (b.slides #- '{29,lines,0}')::text) <> 0 then
    raise exception '358: ks5-20 moved beyond its one sign off line';
  end if;
end $$;

